pug:
div.gmail-blend-screen
    div.gmail-blend-diff
        p.data Web version only
        p.white-title.pb16.pt16 {{ text_1 }}
        p.white-text.pb24  {{ text_2 }}
        table.w280(align="left")
            tr
                td.butt.pb0
                    a.butt-link(href="{{ href_1 }}" universal="true" target="_blank") {{ text_3 }}

styl:
u + .body .gmail-blend-screen { background: #000;
  mix-blend-mode: screen; }
u + .body .gmail-blend-diff { background: #000;
  mix-blend-mode: difference; }
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.data { display: inline-block;
  padding: 6px 16px;
  background: url("https://fsms.quadcode.com/storage/public/d7/ae/a4qnsqgk5ucdfoj0/bg-data1.png") center top no-repeat;
  background-size: cover;
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left; }
@media screen and (max-width: 600px) {
  .data { font-size: 14px !important; }
}
.white-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  color: #f9f9f9;
  word-break: break-word; }
@media screen and (max-width: 600px) {
  .white-title { font-size: 26px !important;
    line-height: 32px !important; }
}
.white-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff; }
@media screen and (max-width: 600px) {
  .white-text { padding-right: 0 !important; }
}
.pb16 { padding-bottom: 16px; }
.pb24 { padding-bottom: 24px; }
.pt16 { padding-top: 16px; }
